const fs=require('node:fs');
fs.mkdirSync('frontend/shared/maps',{recursive:true});
const js=fs.readFileSync('node_modules/leaflet/dist/leaflet.js','utf8').replace(/\/\/# sourceMappingURL=.*$/m,'');
const css=fs.readFileSync('node_modules/leaflet/dist/leaflet.css','utf8');
const license=fs.readFileSync('node_modules/leaflet/LICENSE','utf8');
fs.writeFileSync('frontend/shared/maps/vendor.cjs','// Leaflet 1.9.4, BSD-2-Clause; generated by scripts/bundle-map-library.cjs\nmodule.exports='+JSON.stringify({js,css,license})+';\n');
